const updateCardInvoice=(transaction:any,adjustment:number)=>{if(transaction?.type!=='out')return;const cardName=transaction.card||((String(transaction.payment||'').toLocaleLowerCase('pt-BR').includes('crédito'))?transaction.account:'');if(!cardName)return;try{const cards=JSON.parse(localStorage.getItem('juntos-cards')||'[]');const updated=cards.map((card:any)=>{const label=card.last4?card.bank+' final '+card.last4:card.bank;return label===cardName?{...card,invoice:Math.max(0,Number(card.invoice||0)+adjustment)}:card});localStorage.setItem('juntos-cards',JSON.stringify(updated));window.dispatchEvent(new Event('juntos-cards-updated'))}catch{}};

