function Avatar({ who, small = false, label }: { who: "R" | "M"; small?: boolean; label?: string }) {
  return <div className={`avatar ${small ? "small" : ""} ${who === "M" ? "mariana" : "rafael"}`}>{(label||who).trim().charAt(0).toUpperCase()}</div>;
}

function Logo() {
  return <div className="logo"><span><Heart size={17} fill="currentColor" /></span><div>Juntos <b>Finance</b></div></div>;
}

function MetricCard({ label, value, detail, icon: Icon, tone = "default", hide = false, onToggleHide }: { label: string; value: string; detail?: string; icon: ComponentType<{size?: number}>; tone?: string; hide?: boolean; onToggleHide?:()=>void }) {
  return <article className={`metric card ${tone}`}>
    <div className="metric-head"><span>{label}</span><div className="metric-head-actions">{onToggleHide?<button type="button" className="metric-privacy-button" onClick={onToggleHide} aria-label={`${hide?'Mostrar':'Ocultar'} valor de ${label}`} title={`${hide?'Mostrar':'Ocultar'} valor`} aria-pressed={hide}><Icon size={18}/></button>:<i><Icon size={18}/></i>}</div></div>
    <strong>{hide ? "••••••" : value}</strong>
    {detail&&<small>{detail}</small>}
  </article>;
}

function CategoryExpenseTooltip({ active, payload }: { active?: boolean; payload?: any[] }) {
  const item = payload?.[0]?.payload;
  if (!active || !item) return null;
  return <div className="category-expense-tooltip" style={{ backgroundColor: '#ffffff', color: '#271821', opacity: 1, border: '1px solid #d9c7d0' }}><span><i style={{ background: item.color }}/>{item.name}</span><strong>{brl(Number(item.value) || 0)}</strong></div>;
}
function NewTransactionButton({onSelect}:{onSelect:(type:string)=>void}){
  const [open,setOpen]=useState(false);
  const menuRef=useRef<HTMLDivElement>(null);
  useEffect(()=>{if(!open)return;const close=(event:PointerEvent)=>{if(!menuRef.current?.contains(event.target as Node))setOpen(false)};const closeOnEscape=(event:KeyboardEvent)=>{if(event.key==='Escape')setOpen(false)};document.addEventListener('pointerdown',close);document.addEventListener('keydown',closeOnEscape);return()=>{document.removeEventListener('pointerdown',close);document.removeEventListener('keydown',closeOnEscape)}},[open]);
  return <div className="new-transaction-menu" ref={menuRef}><button className="primary" onClick={()=>setOpen(!open)} aria-expanded={open} aria-label="Nova transação"><Plus size={18}/><span className="new-transaction-label">Nova transação</span><ChevronDown className="new-transaction-chevron" size={16}/></button>{open&&<div className="new-transaction-options"><button onClick={()=>{onSelect('Receita');setOpen(false)}}><ArrowUpRight size={17}/><span><b>Receita</b><small>Registrar uma entrada</small></span></button><button onClick={()=>{onSelect('Despesa');setOpen(false)}}><ArrowDownLeft size={17}/><span><b>Despesa</b><small>Registrar um gasto</small></span></button><button onClick={()=>{onSelect('Transferência');setOpen(false)}}><Repeat2 size={17}/><span><b>Transferência</b><small>Mover dinheiro entre contas</small></span></button></div>}</div>;
}
function Dashboard({ onNew, onAi, hidden, onTogglePrivacy, people, currentName, isCouple }: { onNew: (type?:string) => void; onAi: () => void; hidden: boolean; onTogglePrivacy:()=>void; people:any; currentName?:string; isCouple:boolean }) {
  const [period,setPeriod]=useState(()=>new Intl.DateTimeFormat('en-CA').format(new Date()).slice(0,7));
  const [dashboardItems,setDashboardItems]=useState<any[]>([]);
  const [dashboardGoals,setDashboardGoals]=useState<any[]>([]);
  const [dashboardCards,setDashboardCards]=useState<any[]>([]);
  const [calendarEvents,setCalendarEvents]=useState<any[]>([]);
  const [customizing,setCustomizing]=useState(false);
  const [draggedDashboardCard,setDraggedDashboardCard]=useState<{column:'left'|'right';key:string}|null>(null);
  const [dashboardTransactionMenu,setDashboardTransactionMenu]=useState<number|null>(null);
  const [dashboardTransactionEditor,setDashboardTransactionEditor]=useState<any|null>(null);
  const [showBehaviorExpenses,setShowBehaviorExpenses]=useState(false);
  const [hideDashboardIncome,setHideDashboardIncome]=useState(false);
  const [dashboardMetricVisibility,setDashboardMetricVisibility]=useState({balance:true,income:true,expense:true});
  const [behaviorFilter,setBehaviorFilter]=useState<'all'|'fixed'|'variable'|'installments'>('all');
  const [selectedCategoryExpense,setSelectedCategoryExpense]=useState<any|null>(null);
  const categoryChartRef=useRef<HTMLDivElement>(null);
  useEffect(()=>{if(!selectedCategoryExpense)return;const clearSelection=(event:PointerEvent)=>{if(!categoryChartRef.current?.contains(event.target as Node))setSelectedCategoryExpense(null)};document.addEventListener('pointerdown',clearSelection);return()=>document.removeEventListener('pointerdown',clearSelection)},[selectedCategoryExpense]);
  const [dashboardPrefs,setDashboardPrefs]=useState({metrics:true,invoices:true,cashflow:true,categories:true,expenseBehavior:true,activity:true,alerts:true,goals:true});
  const [dashboardOrder,setDashboardOrder]=useState({left:['cashflow','activity','goals'],right:['categories','expenseBehavior','alerts']});
  const [draftDashboardPrefs,setDraftDashboardPrefs]=useState({metrics:true,invoices:true,cashflow:true,categories:true,expenseBehavior:true,activity:true,alerts:true,goals:true});
  const [draftDashboardOrder,setDraftDashboardOrder]=useState({left:['cashflow','activity','goals'],right:['categories','expenseBehavior','alerts']});
  const normalizeDashboardOrder=(saved:any)=>{const keys=['cashflow','activity','goals','categories','expenseBehavior','alerts'];const leftDefaults=['cashflow','activity','goals'];const rightDefaults=['categories','expenseBehavior','alerts'];const unique=(items:unknown,taken:Set<string>)=>Array.isArray(items)?items.filter((item):item is string=>typeof item==='string'&&keys.includes(item)&&!taken.has(item)).filter(item=>{taken.add(item);return true}):[];const taken=new Set<string>();const left=unique(saved?.left,taken);const right=unique(saved?.right,taken);leftDefaults.forEach(key=>{if(!taken.has(key)){left.push(key);taken.add(key)}});rightDefaults.forEach(key=>{if(!taken.has(key)){right.push(key);taken.add(key)}});return {left,right}};
  const todayLabel=new Intl.DateTimeFormat('pt-BR',{weekday:'long',day:'2-digit',month:'long'}).format(new Date()).replace(/^./,letter=>letter.toUpperCase());
  useEffect(()=>{const loadTransactions=()=>{const saved=localStorage.getItem('juntos-transactions');setDashboardItems(saved?JSON.parse(saved):transactions)};loadTransactions();window.addEventListener('juntos-transactions-updated',loadTransactions);return()=>window.removeEventListener('juntos-transactions-updated',loadTransactions)},[]);
  useEffect(()=>{const loadGoals=()=>{try{setDashboardGoals(JSON.parse(localStorage.getItem('juntos-goals')||'[]'))}catch{setDashboardGoals([])}};loadGoals();window.addEventListener('juntos-goals-updated',loadGoals);return()=>window.removeEventListener('juntos-goals-updated',loadGoals)},[]);
  useEffect(()=>{const loadCards=()=>{try{setDashboardCards(JSON.parse(localStorage.getItem('juntos-cards')||'[]'))}catch{setDashboardCards([])}};loadCards();window.addEventListener('juntos-cards-updated',loadCards);window.addEventListener('juntos-cloud-synced',loadCards);return()=>{window.removeEventListener('juntos-cards-updated',loadCards);window.removeEventListener('juntos-cloud-synced',loadCards)}},[]);
  useEffect(()=>{const load=()=>{try{setCalendarEvents(JSON.parse(localStorage.getItem('juntos-calendar-events')||'[]'));const saved=JSON.parse(localStorage.getItem('juntos-dashboard-prefs')||'null');if(saved)setDashboardPrefs(previous=>({...previous,...saved}));const savedOrder=JSON.parse(localStorage.getItem('juntos-dashboard-order')||'null');if(savedOrder)setDashboardOrder(normalizeDashboardOrder(savedOrder))}catch{}};load();window.addEventListener('juntos-calendar-updated',load);window.addEventListener('juntos-cloud-synced',load);return()=>{window.removeEventListener('juntos-calendar-updated',load);window.removeEventListener('juntos-cloud-synced',load)}},[]);
  const openDashboardConfig=()=>{setDraftDashboardPrefs({...dashboardPrefs});setDraftDashboardOrder({left:[...dashboardOrder.left],right:[...dashboardOrder.right]});setCustomizing(true)};
  const saveDashboardConfig=()=>{const nextPrefs={...draftDashboardPrefs};const nextOrder=normalizeDashboardOrder(draftDashboardOrder);setDashboardPrefs(nextPrefs);setDashboardOrder(nextOrder);localStorage.setItem('juntos-dashboard-prefs',JSON.stringify(nextPrefs));localStorage.setItem('juntos-dashboard-order',JSON.stringify(nextOrder));setCustomizing(false);appAction('Configuração do resumo salva.')};
  const toggleWidget=(key:keyof typeof draftDashboardPrefs)=>setDraftDashboardPrefs(previous=>({...previous,[key]:!previous[key]}));
  const moveDashboardCard=(column:'left'|'right',key:string,direction:-1|1)=>setDraftDashboardOrder(previous=>{const flat=[...previous.left,...previous.right];const index=flat.indexOf(key);const target=index+direction;if(index<0||target<0||target>=flat.length)return previous;[flat[index],flat[target]]=[flat[target],flat[index]];const leftSize=previous.left.length;return {left:flat.slice(0,leftSize),right:flat.slice(leftSize)}});
  const reorderDashboardCard=(column:'left'|'right',key:string,targetKey:string)=>setDraftDashboardOrder(previous=>{const flat=[...previous.left,...previous.right];const from=flat.indexOf(key);const to=flat.indexOf(targetKey);if(from<0||to<0||from===to)return previous;flat.splice(from,1);flat.splice(to,0,key);const leftSize=previous.left.length;return {left:flat.slice(0,leftSize),right:flat.slice(leftSize)}});
const persistDashboardTransactions=(next:any[])=>{localStorage.setItem('juntos-transactions',JSON.stringify(next));setDashboardItems(next);window.dispatchEvent(new Event('juntos-transactions-updated'))};
  const editDashboardTransaction=(item:any,mode:'edit'|'value')=>{const createdAt=item.createdAt||`${item.dateInput||new Intl.DateTimeFormat('en-CA').format(new Date())}T12:00`;setDashboardTransactionEditor({mode,item,form:{...item,value:new Intl.NumberFormat('pt-BR',{minimumFractionDigits:2,maximumFractionDigits:2}).format(Number(item.value)||0),createdAt:createdAt.slice(0,16)}});setDashboardTransactionMenu(null)};
  const saveDashboardTransaction=(event:React.FormEvent)=>{event.preventDefault();if(!dashboardTransactionEditor)return;const form=dashboardTransactionEditor.form;const value=Number(String(form.value).replace(/[.]/g,'').replace(',','.'));if(Number.isNaN(value)||value<0)return;const dateInput=(form.createdAt||'').slice(0,10)||form.dateInput;const date=dateInput?new Intl.DateTimeFormat('pt-BR',{day:'2-digit',month:'short'}).format(new Date(dateInput+'T12:00:00')).replace('.',''):form.date;persistDashboardTransactions(dashboardItems.map(item=>item.id===dashboardTransactionEditor.item.id?{...item,...form,value,dateInput,date}:item));setDashboardTransactionEditor(null);appAction('Transação atualizada com sucesso.')};
  const removeDashboardTransaction=async(item:any)=>{if(!await confirmDialog(`Excluir “${item.title}”?`))return;updateCardInvoice(item,-Number(item.value||0));persistDashboardTransactions(dashboardItems.filter(entry=>entry.id!==item.id));setDashboardTransactionMenu(null);appAction('Transação excluída e fatura atualizada.')};
  const periodItems=dashboardItems.filter(item=>!item.dateInput||item.dateInput.startsWith(period));
  const visibleDashboardItems=periodItems.filter(item=>(!hideDashboardIncome||item.type!=='in')&&!/^sal[aá]rio/i.test(String(item.title||'')+' '+String(item.category||''))).sort((a,b)=>{const dateA=String(a.createdAt||a.dateInput||'');const dateB=String(b.createdAt||b.dateInput||'');return dateB.localeCompare(dateA)||Number(b.id||0)-Number(a.id||0)});
  const monthIncome=periodItems.filter(item=>item.type==='in').reduce((total,item)=>total+Number(item.value||0),0);
  const monthExpense=periodItems.filter(item=>item.type==='out').reduce((total,item)=>total+Number(item.value||0),0);
  const monthSavings=monthIncome-monthExpense;
  const [selectedYear,selectedMonth]=period.split('-').map(Number);const previousDate=new Date(selectedYear,selectedMonth-2,1);const previousKey=previousDate.getFullYear()+'-'+String(previousDate.getMonth()+1).padStart(2,'0');const previousItems=dashboardItems.filter(item=>item.dateInput?.startsWith(previousKey));const previousResult=previousItems.filter(item=>item.type==='in').reduce((sum,item)=>sum+Number(item.value||0),0)-previousItems.filter(item=>item.type==='out').reduce((sum,item)=>sum+Number(item.value||0),0);const comparison=previousResult===0?(monthSavings===0?0:100):Math.round((monthSavings-previousResult)/Math.abs(previousResult)*100);
  const today=new Intl.DateTimeFormat('en-CA').format(new Date());const futureLimitDate=new Date();futureLimitDate.setDate(futureLimitDate.getDate()+30);const futureLimit=new Intl.DateTimeFormat('en-CA').format(futureLimitDate);const overdueLimitDate=new Date();overdueLimitDate.setDate(overdueLimitDate.getDate()-30);const overdueLimit=new Intl.DateTimeFormat('en-CA').format(overdueLimitDate);const futureTransactions=dashboardItems.filter(item=>item.type==='out'&&item.dateInput>=today&&item.dateInput<=futureLimit);const projectedBalance=monthSavings+futureTransactions.reduce((sum,item)=>sum+(item.type==='in'?Number(item.value||0):-Number(item.value||0)),0);const dueCalendarEvents=calendarEvents.filter(item=>item.type!=='income'&&item.date>=overdueLimit&&item.date<=futureLimit&&!item.paid).map(item=>({...item,dateInput:item.date,category:item.category||'Calendário'}));const upcomingPayments=[...dueCalendarEvents,...futureTransactions].sort((a,b)=>(a.dateInput||'').localeCompare(b.dateInput||'')).slice(0,5);const dueStatus=(dateInput:string)=>{const days=Math.ceil((new Date(dateInput+'T12:00:00').getTime()-new Date(today+'T12:00:00').getTime())/86400000);return days<0?{tone:'overdue',label:Math.abs(days)===1?'Vencida há 1 dia':`Vencida há ${Math.abs(days)} dias`}:days===0?{tone:'today',label:'Vence hoje'}:days<=3?{tone:'urgent',label:`Vence em ${days} ${days===1?'dia':'dias'}`}:days<=7?{tone:'warning',label:`Vence em ${days} dias`}:{tone:'upcoming',label:`Vence em ${days} dias`}};
  const chartColors=['#7f2854','#b76a8e','#d79ab6','#8f6bb2','#d39155','#4c8d7b','#6d7f9f'];
  const categoryTotals=Object.entries(periodItems.filter(item=>item.type==='out').reduce((groups:Record<string,number>,item:any)=>{groups[item.category||'Outros']=(groups[item.category||'Outros']||0)+Number(item.value||0);return groups},{})).sort((a,b)=>b[1]-a[1]);
  const categoryExpenses=categoryTotals.map(([name,value],index)=>({name,value,percentage:monthExpense?Math.round(value/monthExpense*100):0,color:chartColors[index%chartColors.length]}));
  const behaviorExpenses=periodItems.filter(item=>item.type==='out'&&!/transfer/i.test(String(item.title||'')+' '+String(item.category||'')));const isInstallmentExpense=(item:any)=>item.schedule==='installments'||Number(item.installments||1)>1;const installmentExpenses=behaviorExpenses.filter(isInstallmentExpense);const fixedExpenses=behaviorExpenses.filter(item=>!isInstallmentExpense(item)&&(item.behavior||(item.fixedMonthly?'fixed':'variable'))==='fixed');const variableExpenses=behaviorExpenses.filter(item=>!isInstallmentExpense(item)&&(item.behavior||(item.fixedMonthly?'fixed':'variable'))!=='fixed');const fixedExpense=fixedExpenses.reduce((sum,item)=>sum+Number(item.value||0),0);const variableExpense=variableExpenses.reduce((sum,item)=>sum+Number(item.value||0),0);const installmentExpense=installmentExpenses.reduce((sum,item)=>sum+Number(item.value||0),0);const behaviorTotal=fixedExpense+variableExpense+installmentExpense;const behaviorExpenseData=[{name:'Fixos',value:fixedExpense,percentage:behaviorTotal?Math.round(fixedExpense/behaviorTotal*100):0,color:'#6d3bd1'},{name:'Variáveis',value:variableExpense,percentage:behaviorTotal?Math.round(variableExpense/behaviorTotal*100):0,color:'#d39155'},{name:'Parcelados',value:installmentExpense,percentage:behaviorTotal?Math.round(installmentExpense/behaviorTotal*100):0,color:'#3b82f6'}];const behaviorExpenseLabel=(item:any)=>isInstallmentExpense(item)?'Parcelado':(item.behavior||(item.fixedMonthly?'fixed':'variable'))==='fixed'?'Fixo':'Variável';const behaviorExpenseKey=(item:any)=>isInstallmentExpense(item)?'installments':(item.behavior||(item.fixedMonthly?'fixed':'variable'))==='fixed'?'fixed':'variable';const visibleBehaviorExpenses=behaviorFilter==='all'?behaviorExpenses:behaviorExpenses.filter(item=>behaviorExpenseKey(item)===behaviorFilter);const visibleBehaviorData=behaviorFilter==='all'?behaviorExpenseData:behaviorExpenseData.filter(item=>item.name===(behaviorFilter==='fixed'?'Fixos':behaviorFilter==='variable'?'Variáveis':'Parcelados'));const visibleBehaviorTotal=visibleBehaviorData.reduce((sum,item)=>sum+item.value,0);
  const dashboardCashflow=Array.from({length:6},(_,offset)=>{const [year,month]=period.split('-').map(Number);const date=new Date(year,month-1-(5-offset),1);const key=date.getFullYear()+'-'+String(date.getMonth()+1).padStart(2,'0');const items=dashboardItems.filter(item=>item.dateInput?.startsWith(key));return {m:new Intl.DateTimeFormat('pt-BR',{month:'short'}).format(date).replace('.',''),receita:items.filter(item=>item.type==='in').reduce((sum,item)=>sum+Number(item.value||0),0),despesa:items.filter(item=>item.type==='out').reduce((sum,item)=>sum+Number(item.value||0),0)}});
  const periodOptions=Array.from({length:36},(_,i)=>{const date=new Date(2025+Math.floor(i/12),i%12,1);return {value:date.getFullYear()+'-'+String(date.getMonth()+1).padStart(2,'0'),label:new Intl.DateTimeFormat('pt-BR',{month:'long',year:'numeric'}).format(date).replace(/^./,x=>x.toUpperCase())}});
  return <>
    <section className="welcome">
      <div><p>{todayLabel}</p><h1>Olá, {(currentName||people.Rafael.name).trim().split(' ')[0]} <span>👋</span></h1><small>{isCouple?'Dinheiro organizado, planos construídos juntos.':'Seu dinheiro, seus planos, suas escolhas.'}</small></div>
      <div className="welcome-actions">
        <label className="ghost period period-picker"><CalendarDays size={17}/><span>{periodOptions.find(x=>x.value===period)?.label}</span><ChevronDown size={16}/><select value={period} onChange={e=>setPeriod(e.target.value)} aria-label="Selecionar mês e ano">{periodOptions.map(x=><option value={x.value} key={x.value}>{x.label}</option>)}</select></label>
        <button className={`ghost privacy-toggle ${hidden ? 'active' : ''}`} onClick={onTogglePrivacy} aria-pressed={hidden} title={hidden?'Mostrar valores':'Ocultar valores'}>{hidden ? <Eye size={18}/> : <EyeOff size={18}/>}<span>{hidden?'Mostrar valores':'Modo privado'}</span></button><button className="ghost" onClick={openDashboardConfig}><Settings size={17}/> Personalizar</button><NewTransactionButton onSelect={onNew}/>
      </div>
    </section>

    {customizing&&<div className="dashboard-config-backdrop"><section className="dashboard-config" role="dialog" aria-modal="true" aria-label="Configurar resumo">
      <header className="dashboard-config-header"><button className="config-back" onClick={()=>setCustomizing(false)} aria-label="Voltar"><ArrowRight size={22}/></button><h2>Configurar resumo</h2><button className="config-save" onClick={saveDashboardConfig}>Salvar</button></header>
      <div className="dashboard-config-intro"><Settings size={22}/><div><h3>Escolha os cards que devem aparecer na tela de resumo</h3><p>Alguns cards são específicos para cada coluna. Arraste para mudar a ordem.</p></div></div>
      <div className="dashboard-general-switches"><div><span>Resumo financeiro</span><button className={`config-switch ${draftDashboardPrefs.metrics?'on':''}`} onClick={()=>toggleWidget('metrics')} aria-pressed={draftDashboardPrefs.metrics}><i/></button></div><div><span>Faturas dos cartões</span><button className={`config-switch ${draftDashboardPrefs.invoices?'on':''}`} onClick={()=>toggleWidget('invoices')} aria-pressed={draftDashboardPrefs.invoices}><i/></button></div></div>
      <div className="dashboard-config-columns">{(['left','right'] as const).map(column=><section className="config-card-column" key={column}><h3>{column==='left'?'Cards da esquerda':'Cards da direita'}</h3><div>{draftDashboardOrder[column].map((key,index)=>{const labels:Record<string,string>={cashflow:'Receitas vs Despesas',activity:'Movimentações recentes',goals:'Minhas metas',categories:'Gastos por categoria',expenseBehavior:'Gastos fixos e variáveis',alerts:'Alertas e contas a vencer'};return <article className={`config-card-row ${draggedDashboardCard?.key===key?'dragging':''}`} onDragOver={event=>{event.preventDefault();event.dataTransfer.dropEffect='move'}} onDrop={event=>{event.preventDefault();if(draggedDashboardCard)reorderDashboardCard(column,draggedDashboardCard.key,key);setDraggedDashboardCard(null)}} key={key}><button type="button" className="config-drag-handle" draggable onDragStart={event=>{event.stopPropagation();event.dataTransfer.effectAllowed='move';event.dataTransfer.setData('text/plain',key);setDraggedDashboardCard({column,key})}} onDragEnd={()=>setDraggedDashboardCard(null)} aria-label={`Arrastar ${labels[key]}`} title="Arraste para reorganizar"><GripVertical size={20}/></button><span>{labels[key]}</span><div className="config-mobile-order"><button type="button" title="Mover para cima" aria-label={`Mover ${labels[key]} para cima`} onClick={event=>{event.stopPropagation();moveDashboardCard(column,key,-1)}} disabled={[...draftDashboardOrder.left,...draftDashboardOrder.right].indexOf(key)===0}><ArrowUp size={14}/></button><button type="button" title="Mover para baixo" aria-label={`Mover ${labels[key]} para baixo`} onClick={event=>{event.stopPropagation();moveDashboardCard(column,key,1)}} disabled={[...draftDashboardOrder.left,...draftDashboardOrder.right].indexOf(key)===[...draftDashboardOrder.left,...draftDashboardOrder.right].length-1}><ArrowDown size={14}/></button></div><button className={`config-switch ${draftDashboardPrefs[key as keyof typeof draftDashboardPrefs]?'on':''}`} onClick={()=>toggleWidget(key as keyof typeof draftDashboardPrefs)} aria-pressed={draftDashboardPrefs[key as keyof typeof draftDashboardPrefs]}><i/></button></article>})}</div></section>)}</div>
    </section></div>}
    <div className="metrics-grid compact dashboard-metrics" style={{display:dashboardPrefs.metrics?'grid':'none'}}>
      <MetricCard label="Saldo em contas" value={brl(Math.max(0,monthSavings))} detail="Contas e PIX" icon={WalletCards} tone="balance" hide={hidden||!dashboardMetricVisibility.balance} onToggleHide={()=>setDashboardMetricVisibility(value=>({...value,balance:!value.balance}))}/>
      <MetricCard label={`Receitas (${period})`} value={`+ ${brl(monthIncome)}`} detail="Salários e entradas" icon={ArrowUpRight} tone="positive" hide={hidden||!dashboardMetricVisibility.income} onToggleHide={()=>setDashboardMetricVisibility(value=>({...value,income:!value.income}))}/>
      <MetricCard label={`Despesas (${period})`} value={`- ${brl(monthExpense)}`} detail="Gastos registrados" icon={ArrowDownLeft} tone="negative" hide={hidden||!dashboardMetricVisibility.expense} onToggleHide={()=>setDashboardMetricVisibility(value=>({...value,expense:!value.expense}))}/>
    </div>

    {dashboardPrefs.invoices&&dashboardCards.length>0&&<section className="dashboard-invoices"><div className="section-title"><div><h3>Faturas dos cartões</h3><p>Valores atuais de cada cartão cadastrado</p></div><button className="text-button" onClick={()=>appAction({page:'Cartões'})}>Gerenciar <ArrowRight size={15}/></button></div><div className="dashboard-invoice-grid">{dashboardCards.map(item=>{const invoice=Number(item.invoice)||0;const limit=Number(item.limit)||0;const rawPct=limit?Math.round(invoice/limit*100):0;const pct=Math.min(100,rawPct);const overLimit=invoice>limit;return <button className={`card dashboard-invoice ${overLimit?'over-limit':''}`} key={item.id} onClick={()=>appAction({page:'Cartões'})}><span className="card-bank-brand">{item.bankDomain&&<img src={bankLogo(item.bankDomain)} alt=""/>}<b>{item.bank}</b><i className={invoice>0?'open':'closed'}>{invoice>0?'Aberta':'Fechada'}</i></span><strong>{hidden?'••••':brl(invoice)}</strong><small>{hidden?'Valores ocultos':<>de {brl(limit)} · {pct}% usado</>}</small>{!hidden&&overLimit&&<span className="invoice-limit-alert exceeded"><AlertTriangle size={13}/> Limite ultrapassado</span>}<div><span style={{width:`${pct}%`}}/></div></button>})}</div></section>}

    <div className="dashboard-columns">
      <div className="dashboard-column">
        {dashboardPrefs.cashflow&&<section className="card chart-card wide cashflow-bars" style={{order:[...dashboardOrder.left,...dashboardOrder.right].indexOf('cashflow')}}>
        <div className="section-title"><div><h3>Receitas vs Despesas</h3></div></div>
        <div className="chart-wrap"><ResponsiveContainer width="100%" height="100%"><ReBarChart data={dashboardCashflow} margin={{top:12,right:8,left:8,bottom:0}} barGap={5} barCategoryGap="16%"><CartesianGrid vertical={false} stroke="#eee7eb"/><XAxis dataKey="m" axisLine={false} tickLine={false} tick={{fill:'#6f686c',fontSize:11}}/><YAxis hide/><Tooltip cursor={{fill:'rgba(112,34,68,.04)'}} itemSorter={(item)=>item.dataKey === 'receita' ? -1 : 1} formatter={(v,name)=>[brl(Number(v)),String(name)]}/><Bar dataKey="receita" name="Receita" fill="#2f9961" radius={[6,6,0,0]} maxBarSize={72}/><Bar dataKey="despesa" name="Despesa" fill="#8b263f" radius={[6,6,0,0]} maxBarSize={72}/></ReBarChart></ResponsiveContainer></div>
        <div className="legend bar-legend"><span><i className="income-bar"/>Receita</span><span><i className="expense-bar"/>Despesa</span></div>
      </section>}
        {dashboardPrefs.activity&&<section className="card transactions-card" style={{order:[...dashboardOrder.left,...dashboardOrder.right].indexOf('activity')}}>
        <div className="section-title"><div><h3>Movimentações recentes</h3><p>Suas últimas transações</p></div><div className="dashboard-transaction-tools"><button type="button" className="text-button" onClick={()=>setHideDashboardIncome(value=>!value)} aria-pressed={hideDashboardIncome}>{hideDashboardIncome?'Mostrar receitas':'Ocultar receitas'}</button><button className="text-button" onClick={()=>appAction({page:'Transações'})}>Ver todas <ArrowRight size={15}/></button></div></div>
        <div className="dashboard-transaction-list"><div className="dashboard-transaction-head"><span/><b>Movimentação</b><span className="dashboard-transaction-meta-head"><b>Titular</b><b>Conta</b><b>Data</b></span><b>Valor</b><span/></div>{visibleDashboardItems.length?visibleDashboardItems.slice(0,5).map(t=><article className="dashboard-transaction" key={t.id}><div className={`transaction-icon ${t.type}`}>{categoryIconFor(t.category,t.icon)}</div><div className="dashboard-transaction-main"><b>{displayTitle(people,t.title)}</b><small>{t.notes||t.category||'Sem descrição'}</small></div><div className="dashboard-transaction-meta"><span><b>{displayPerson(people,t.person)}</b></span><span><b>{t.account||t.card||'Não informada'}</b></span><span><b>{t.createdAt?`${new Date(t.createdAt).toLocaleDateString('pt-BR',{day:'2-digit',month:'2-digit'})} · ${new Date(t.createdAt).toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit'})}`:t.dateInput?`${new Date(t.dateInput+'T12:00:00').toLocaleDateString('pt-BR',{day:'2-digit',month:'2-digit'})} · --:--`:`${t.date} · --:--`}</b></span></div><strong className={t.type}>{hidden?'••••':<>{t.type === "in" ? "+" : "−"} {brl(t.value)}</>}</strong><div className="dashboard-transaction-actions"><button className="icon-button" onClick={()=>setDashboardTransactionMenu(dashboardTransactionMenu===t.id?null:t.id)} aria-label="Ações da transação"><MoreHorizontal size={18}/></button>{dashboardTransactionMenu===t.id&&<div className="dashboard-transaction-menu"><button onClick={()=>editDashboardTransaction(t,'edit')}>Editar</button><button onClick={()=>editDashboardTransaction(t,'value')}>Alterar valor</button><button className="danger" onClick={()=>removeDashboardTransaction(t)}>Excluir</button></div>}</div></article>):<div className="organizer-empty">Nenhuma transação cadastrada.</div>}</div>
      </section>}
        <section className="goals-section" style={{display:dashboardPrefs.goals?'block':'none',order:[...dashboardOrder.left,...dashboardOrder.right].indexOf('goals')}}><div className="section-title"><div><h3>Minhas metas</h3><p>Transformando planos em conquistas</p></div><button className="text-button" onClick={()=>appAction({page:"Metas"})}>Ver todas <ArrowRight size={15}/></button></div><div className="goals-grid">{dashboardGoals.length?dashboardGoals.map(g=>{const pct=Math.round(g.current/g.total*100);return <article className="card goal" key={g.title}><div className="goal-top"><i>{g.emoji}</i><span><b>{g.title}</b><small>Meta para {g.date}</small></span><strong>{pct}%</strong></div><div className="progress"><span style={{width:`${pct}%`,background:g.color}}/></div><div className="goal-values"><b>{hidden ? "••••" : brl(g.current)}</b><span>de {hidden ? "••••" : brl(g.total)}</span></div></article>}):<div className="organizer-empty">Nenhuma meta cadastrada.</div>}</div></section>
      </div>
      <div className="dashboard-column">
        {dashboardPrefs.categories&&<section className="card chart-card donut-card" style={{order:[...dashboardOrder.left,...dashboardOrder.right].indexOf('categories')}}>
        <div className="section-title"><div><h3>Gastos por categoria</h3><p>{periodOptions.find(option=>option.value===period)?.label}</p></div><button className="icon-button" onClick={()=>appAction({page:'Transações'})} aria-label="Ver gastos por categoria"><MoreHorizontal size={19}/></button></div>
        <div className="donut-wrap" ref={categoryChartRef}><ResponsiveContainer width="100%" height="100%"><PieChart><Pie data={categoryExpenses} dataKey="value" innerRadius={54} outerRadius={78} paddingAngle={3} startAngle={90} endAngle={-270} onClick={(data:any)=>setSelectedCategoryExpense(data)}>{categoryExpenses.map((x)=><Cell key={x.name} fill={x.color}/>)}</Pie></PieChart></ResponsiveContainer><div className="donut-label"><b>{hidden?'••••':brl(monthExpense)}</b><small>Total gasto</small></div></div><div className="category-expense-selection" aria-live="polite">{selectedCategoryExpense?<><span><i style={{background:selectedCategoryExpense.color}}/>{selectedCategoryExpense.name}</span><strong>{hidden?'••••':brl(Number(selectedCategoryExpense.value)||0)}</strong></>:<small>Toque em uma cor do gráfico para ver o gasto.</small>}</div>
        <div className="expense-legend">{categoryExpenses.map(x=><div key={x.name}><span><i style={{background:x.color}}/>{x.name}</span><b>{x.percentage}%</b></div>)}</div>
      </section>}
        {dashboardPrefs.expenseBehavior&&<section className="card chart-card donut-card behavior-dashboard-card" style={{order:[...dashboardOrder.left,...dashboardOrder.right].indexOf('expenseBehavior')}}><div className="section-title"><div><h3>Gastos fixos e variáveis</h3><p>{periodOptions.find(option=>option.value===period)?.label}</p></div><button className="icon-button" onClick={()=>appAction({page:'Transações'})} aria-label="Ver gastos fixos e variáveis"><MoreHorizontal size={19}/></button></div><div className="behavior-dashboard-filters">{[['all','Todos'],['fixed','Fixos'],['variable','Variáveis'],['installments','Parcelados']].map(([value,label])=><button type="button" className={behaviorFilter===value?'active':''} onClick={()=>setBehaviorFilter(value as typeof behaviorFilter)} key={value}>{label}</button>)}</div><div className="donut-wrap"><ResponsiveContainer width="100%" height="100%"><PieChart><Pie data={visibleBehaviorData} dataKey="value" innerRadius={54} outerRadius={78} paddingAngle={4} startAngle={90} endAngle={-270}>{visibleBehaviorData.map(item=><Cell key={item.name} fill={item.color}/>)}</Pie><Tooltip formatter={value=>brl(Number(value))}/></PieChart></ResponsiveContainer><div className="donut-label"><b>{hidden?'••••':brl(visibleBehaviorTotal)}</b><small>Total gasto</small></div></div><div className="behavior-dashboard-legend">{visibleBehaviorData.map(item=><div key={item.name}><span><i style={{background:item.color}}/><b>{item.name}</b><small>{item.percentage}%</small></span><strong>{hidden?'••••':brl(item.value)}</strong></div>)}</div><button type="button" className="behavior-show-expenses" onClick={()=>setShowBehaviorExpenses(previous=>!previous)}>{showBehaviorExpenses?'Ocultar gastos':'Mostrar gastos'} <ChevronDown size={15}/></button>{showBehaviorExpenses&&<div className="behavior-expense-list">{visibleBehaviorExpenses.length?visibleBehaviorExpenses.slice(0,8).map(item=><button type="button" onClick={()=>appAction({page:'Transações'})} key={item.id}><span><b>{displayTitle(people,item.title)}</b><small>{item.category||'Outros'} · {behaviorExpenseLabel(item)}</small></span><strong>{hidden?'••••':brl(Number(item.value||0))}</strong></button>):<p>Nenhum gasto registrado neste mês.</p>}{visibleBehaviorExpenses.length>8&&<button type="button" className="behavior-view-all" onClick={()=>appAction({page:'Transações'})}>Ver todos os {visibleBehaviorExpenses.length} gastos</button>}</div>}</section>}        {dashboardPrefs.alerts&&<aside className="side-stack" style={{order:[...dashboardOrder.left,...dashboardOrder.right].indexOf('alerts')}}>
        <section className="card ai-alerts-card"><div className="ai-alerts-head"><div><h3>Alertas da IA <span>0</span></h3><button onClick={onAi}>IA Conselheira <ChevronRight size={14}/></button></div></div><div className="ai-alert-list"><article><i className="alert-green"><Lightbulb size={18}/></i><div><b>Nenhum alerta por enquanto</b><p>Cadastre transações, contas e metas para receber análises.</p></div></article></div></section>
        <section className="card upcoming payment-alerts"><div className="section-title"><div><h3>Contas a vencer</h3><p>{upcomingPayments.length?`${upcomingPayments.length} alertas nos próximos 30 dias`:'Nenhuma conta próxima do vencimento'}</p></div></div>{upcomingPayments.length?upcomingPayments.map(item=>{const status=dueStatus(item.dateInput);return <button className={`payment-alert ${status.tone}`} onClick={()=>appAction({page:'Calendário'})} key={(item.id||item.title)+'-'+item.dateInput}><i><CalendarDays size={18}/></i><span><b>{item.title}</b><small>{item.category||'Conta'} · {new Date(item.dateInput+'T12:00:00').toLocaleDateString('pt-BR')}</small><em>{status.label}</em></span><strong>{hidden?'••••':item.value?brl(Number(item.value)):'—'}</strong></button>}):<p className="agenda-empty">Tudo em dia! Adicione vencimentos no Calendário para receber alertas.</p>}</section>
      </aside>}
      </div>
    </div>



    {dashboardTransactionEditor&&<div className="modal-backdrop" onMouseDown={event=>event.target===event.currentTarget&&setDashboardTransactionEditor(null)}><form className="modal dashboard-transaction-editor" onSubmit={saveDashboardTransaction}><div className="edit-modal-head"><div><span>MOVIMENTAÇÃO</span><h2>{dashboardTransactionEditor.mode==='value'?'Alterar valor':'Editar transação'}</h2><p>{dashboardTransactionEditor.item.title}</p></div><button type="button" className="icon-button" onClick={()=>setDashboardTransactionEditor(null)}><X/></button></div><div className="dashboard-transaction-form">{dashboardTransactionEditor.mode==='edit'&&<><label className="field-full">Título<input value={dashboardTransactionEditor.form.title||''} onChange={event=>setDashboardTransactionEditor({...dashboardTransactionEditor,form:{...dashboardTransactionEditor.form,title:event.target.value}})} required/></label><label className="field-full">Descrição<textarea value={dashboardTransactionEditor.form.notes||''} onChange={event=>setDashboardTransactionEditor({...dashboardTransactionEditor,form:{...dashboardTransactionEditor.form,notes:event.target.value}})} rows={3}/></label><label>Titular<select value={dashboardTransactionEditor.form.person||'Rafael'} onChange={event=>setDashboardTransactionEditor({...dashboardTransactionEditor,form:{...dashboardTransactionEditor.form,person:event.target.value}})}><option value="Rafael">Você</option><option value="Mariana">Parceiro(a)</option><option>Casal</option></select></label><label>Conta de onde saiu<input value={dashboardTransactionEditor.form.account||''} onChange={event=>setDashboardTransactionEditor({...dashboardTransactionEditor,form:{...dashboardTransactionEditor.form,account:event.target.value}})}/></label><label className="field-full">Data e hora<input type="datetime-local" value={dashboardTransactionEditor.form.createdAt||''} onChange={event=>setDashboardTransactionEditor({...dashboardTransactionEditor,form:{...dashboardTransactionEditor.form,createdAt:event.target.value}})}/></label></>}<label className={dashboardTransactionEditor.mode==='value'?'field-full':''}>Valor<input value={dashboardTransactionEditor.form.value||''} onChange={event=>setDashboardTransactionEditor({...dashboardTransactionEditor,form:{...dashboardTransactionEditor.form,value:formatMoneyInput(event.target.value)}})} inputMode="decimal" required/></label></div><div className="edit-modal-actions"><button type="button" className="ghost" onClick={()=>setDashboardTransactionEditor(null)}>Cancelar</button><button className="primary"><Check size={17}/> Salvar alterações</button></div></form></div>}  </>;
}

function TransactionsPage({ onNew, people, isCouple }: { onNew: (type?:string) => void; people:any; isCouple:boolean }) {
  const [query,setQuery]=useState(''); const [hideIncome,setHideIncome]=useState(false); const [person,setPerson]=useState('Todas'); const [transactionTypeView,setTransactionTypeView]=useState<'all'|'income'|'expense'|'transfer'>('expense'); const [behaviorView,setBehaviorView]=useState<'all'|'fixed'|'variable'|'installments'>('all'); const [period,setPeriod]=useState(()=>new Intl.DateTimeFormat('en-CA').format(new Date()).slice(0,7)); const [openMenu,setOpenMenu]=useState<number|null>(null); const [editing,setEditing]=useState<any|null>(null); const [editForm,setEditForm]=useState<any>({}); const [paymentEditing,setPaymentEditing]=useState<any|null>(null); const [metricVisibility,setMetricVisibility]=useState({total:true}); const [exportOpen,setExportOpen]=useState(false); const exportRef=useRef<HTMLDivElement>(null);
  useEffect(()=>{try{const saved=JSON.parse(localStorage.getItem('juntos-transaction-metrics-visibility')||'null');if(saved)setMetricVisibility(previous=>({...previous,...saved}))}catch{}},[]);
  useEffect(()=>{if(!exportOpen)return;const close=(event:PointerEvent)=>{if(!exportRef.current?.contains(event.target as Node))setExportOpen(false)};const escape=(event:KeyboardEvent)=>{if(event.key==='Escape')setExportOpen(false)};document.addEventListener('pointerdown',close);document.addEventListener('keydown',escape);return()=>{document.removeEventListener('pointerdown',close);document.removeEventListener('keydown',escape)}},[exportOpen]);
  const toggleMetricVisibility=(key:'total')=>setMetricVisibility(previous=>{const next={...previous,[key]:!previous[key]};localStorage.setItem('juntos-transaction-metrics-visibility',JSON.stringify(next));return next});
  const [items,setItems]=useState<any[]>(transactions);
  const [categories,setCategories]=useState<string[]>(DEFAULT_TRANSACTION_CATEGORIES);
  useEffect(()=>{const load=()=>{const saved=localStorage.getItem('juntos-transactions');setItems(saved?JSON.parse(saved):transactions);try{const settings=JSON.parse(localStorage.getItem('juntos-settings')||'{}');const configured=settings.categories;if(Array.isArray(configured))setCategories([...new Set([...DEFAULT_TRANSACTION_CATEGORIES,...configured])])}catch{}};load();window.addEventListener('juntos-transactions-updated',load);window.addEventListener('juntos-cloud-synced',load);return()=>{window.removeEventListener('juntos-transactions-updated',load);window.removeEventListener('juntos-cloud-synced',load)}},[]);
  const persist=(next:any[])=>{setItems(next);localStorage.setItem('juntos-transactions',JSON.stringify(next));window.dispatchEvent(new Event('juntos-transactions-updated'))};
  const openPayment=(t:any)=>{const paid=t.status==='Pago'||t.status==='Efetivada';setPaymentEditing({id:t.id,title:t.title,status:paid?'Pago':'Pendente',paidDate:(t.paidAt||new Date().toISOString()).slice(0,10)})};
  const savePayment=(e:React.FormEvent)=>{e.preventDefault();const paid=paymentEditing.status==='Pago';const today=new Intl.DateTimeFormat('en-CA').format(new Date());const paidDate=paymentEditing.paidDate||today;if(paid&&paidDate>today){appAction('A data do pagamento não pode ser futura.');return}persist(items.map(item=>item.id===paymentEditing.id?{...item,status:paid?'Pago':'Pendente',paidAt:paid?paidDate+'T12:00:00':null}:item));setPaymentEditing(null);appAction(paid?'Pagamento confirmado.':'Despesa marcada como pendente.')};
  const openEdit=(t:any)=>{setEditing(t);setEditForm({...t,behavior:t.behavior||(t.fixedMonthly?'fixed':'variable'),value:String(t.value).replace('.',','),dateInput:t.dateInput||(t.date?.includes('-')?t.date:period+'-'+String(t.date).replace(/\D/g,'').padStart(2,'0'))});setOpenMenu(null)};
  const saveEdit=(e:React.FormEvent)=>{e.preventDefault();const value=Number(String(editForm.value).replace(/[.]/g,'').replace(',','.'));if(!editForm.title?.trim()||Number.isNaN(value))return;persist(items.map(x=>x.id===editing.id?{...x,...editForm,title:editForm.title.trim(),value,date:editForm.dateInput?new Intl.DateTimeFormat('pt-BR',{day:'2-digit',month:'short'}).format(new Date(editForm.dateInput+'T12:00:00')).replace('.',''):x.date}:x));setEditing(null);appAction('Transação atualizada com sucesso.')};
  const remove=async(t:any)=>{if(await confirmDialog(`Excluir “${t.title}”?`)){updateCardInvoice(t,-Number(t.value||0));persist(items.filter(x=>x.id!==t.id));setOpenMenu(null);setEditing(null);appAction('Transação excluída e fatura atualizada.')}};
  const periodItems=items.filter(t=>!t.dateInput||t.dateInput.startsWith(period));
  const transactionBehavior=(t:any)=>t.schedule==='installments'||Number(t.installments||1)>1?'installments':(t.behavior||(t.fixedMonthly?'fixed':'variable'))==='fixed'?'fixed':'variable';const isTransferTransaction=(t:any)=>t.type==='transfer'||/transfer/i.test(String(t.title||'')+' '+String(t.category||''));const matchesTransactionType=(t:any)=>transactionTypeView==='all'||transactionTypeView==='transfer'&&isTransferTransaction(t)||transactionTypeView==='income'&&t.type==='in'&&!isTransferTransaction(t)||transactionTypeView==='expense'&&t.type==='out'&&!isTransferTransaction(t);const normalizePerson=(value:any)=>String(value||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').trim().toLowerCase();const matchesPerson=(t:any)=>{if(person==='Todas')return true;const saved=normalizePerson(t.person);if(person==='Rafael')return saved==='rafael'||saved===normalizePerson(people.Rafael.name);if(person==='Mariana')return saved==='mariana'||saved===normalizePerson(people.Mariana.name);return saved==='rafael'||saved==='mariana'||saved==='casal'||saved==='ambos'||saved==='compartilhada'||saved==='compartilhado'||saved===normalizePerson(people.Rafael.name)||saved===normalizePerson(people.Mariana.name)};const filtered=periodItems.filter(t=>(t.title.toLowerCase().includes(query.toLowerCase())||t.category.toLowerCase().includes(query.toLowerCase()))&&matchesPerson(t)&&(!hideIncome||t.type!=='in')&&matchesTransactionType(t)&&(behaviorView==='all'||transactionBehavior(t)===behaviorView)).sort((a,b)=>{const createdOrder=String(b.createdAt||'').localeCompare(String(a.createdAt||''));return createdOrder||Number(b.id||0)-Number(a.id||0)});
  const income=filtered.filter(t=>t.type==='in').reduce((sum,t)=>sum+Number(t.value),0); const expense=filtered.filter(t=>t.type==='out').reduce((sum,t)=>sum+Number(t.value),0); const result=income-expense; const filteredTotal=filtered.reduce((sum,t)=>sum+Number(t.value||0),0);
  const exportHeaders=['Situação','Descrição','Categoria','Conta','Data da efetivação','Valor'];
  const exportRows=()=>filtered.map(t=>{const transfer=t.type==='transfer'||/transfer/i.test(String(t.title||'')+' '+String(t.category||''));const paid=t.type==='in'||t.status==='Pago'||t.status==='Efetivada';const date=t.type==='in'?(t.dateInput||t.createdAt?.slice(0,10)||''):paid?(t.paidAt?.slice(0,10)||t.dateInput||''):(t.dateInput||'');return [transfer?'Transferência':t.type==='in'?'Receita efetivada':paid?'Pago':'Pendente',displayTitle(people,t.title),t.category||'Outros',t.account||t.card||'Não informada',date?new Date(date+'T12:00:00').toLocaleDateString('pt-BR'):'Não informada',brl((transfer||t.type==='in'?1:-1)*Number(t.value||0))]});
  const exportSummary=()=>{const isTransfer=(t:any)=>t.type==='transfer'||/transfer/i.test(String(t.title||'')+' '+String(t.category||''));const transfers=filtered.filter(isTransfer);const expenses=filtered.filter(t=>t.type==='out'&&!isTransfer(t));const pending=expenses.filter(t=>t.status!=='Pago'&&t.status!=='Efetivada'&&!t.paidAt);const paid=expenses.filter(t=>t.status==='Pago'||t.status==='Efetivada'||t.paidAt);const revenues=filtered.filter(t=>t.type==='in');const revenueValue=revenues.reduce((sum,t)=>sum+Number(t.value||0),0);const expenseValue=expenses.reduce((sum,t)=>sum+Number(t.value||0),0);const generated=new Date();return {revenueCount:revenues.filter(t=>!isTransfer(t)).length,revenueValue:revenues.filter(t=>!isTransfer(t)).reduce((sum,t)=>sum+Number(t.value||0),0),expenseCount:expenses.length,expenseValue,result:revenues.filter(t=>!isTransfer(t)).reduce((sum,t)=>sum+Number(t.value||0),0)-expenseValue,transferCount:transfers.length,transferValue:transfers.reduce((sum,t)=>sum+Number(t.value||0),0),pendingCount:pending.length,pendingValue:pending.reduce((sum,t)=>sum+Number(t.value||0),0),paidCount:paid.length,paidValue:paid.reduce((sum,t)=>sum+Number(t.value||0),0),date:generated.toLocaleDateString('pt-BR'),time:generated.toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit',second:'2-digit'})}};
  const downloadExport=(content:string,type:string,extension:string)=>{const blob=new Blob([content],{type});const url=URL.createObjectURL(blob);const link=document.createElement('a');link.href=url;link.download=`transacoes-${period}.${extension}`;link.click();URL.revokeObjectURL(url);setExportOpen(false);appAction(`Transações exportadas em ${extension.toUpperCase()}.`)};
  const exportCsv=()=>{const escape=(value:any)=>`"${String(value).replace(/"/g,'""')}"`;const summary=exportSummary();const info=[['RESUMO DA EXPORTAÇÃO','QUANTIDADE','VALOR / INFORMAÇÃO'],['Receitas',summary.revenueCount,brl(summary.revenueValue)],['Despesas',summary.expenseCount,brl(summary.expenseValue)],['Resultado','',brl(summary.result)],['Transferências',summary.transferCount,brl(summary.transferValue)],['Pendentes',summary.pendingCount,brl(summary.pendingValue)],['Pagos',summary.paidCount,brl(summary.paidValue)],['Gerado em','',summary.date],['Horário','',summary.time],[],exportHeaders,...exportRows()];downloadExport('\uFEFF'+info.map(row=>row.map(escape).join(';')).join('\r\n'),'text/csv;charset=utf-8','csv')};
  const exportExcel=()=>{const escape=(value:any)=>String(value).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');const summary=exportSummary();const summaryRows=[['Receitas',summary.revenueCount,brl(summary.revenueValue)],['Despesas',summary.expenseCount,brl(summary.expenseValue)],['Resultado','',brl(summary.result)],['Transferências',summary.transferCount,brl(summary.transferValue)],['Pendentes',summary.pendingCount,brl(summary.pendingValue)],['Pagos',summary.paidCount,brl(summary.paidValue)],['Gerado em','',summary.date],['Horário','',summary.time]];downloadExport(`\uFEFF<html><head><meta charset="utf-8"><style>body{font-family:Arial}.summary-title{background:#7f2854;color:#fff;font-size:16px}.summary-head{background:#eadce3;color:#5f1738;font-weight:bold}.summary-label{background:#f8f2f5;font-weight:bold}.summary-count{background:#fff0f5;color:#9b214f;font-size:16px;font-weight:bold;text-align:center}.summary-value{font-weight:bold}.data-head{background:#7f2854;color:#fff;font-weight:bold}td,th{padding:10px;border:1px solid #ddd}</style></head><body><table><tr><th class="summary-title" colspan="6">RESUMO DA EXPORTAÇÃO</th></tr><tr><th class="summary-head">Indicador</th><th class="summary-head">Quantidade</th><th class="summary-head" colspan="4">Valor / informação</th></tr>${summaryRows.map(row=>`<tr><td class="summary-label">${escape(row[0])}</td><td class="summary-count">${escape(row[1])}</td><td class="summary-value" colspan="4">${escape(row[2])}</td></tr>`).join('')}<tr><td colspan="6"></td></tr><tr>${exportHeaders.map(value=>`<th class="data-head">${escape(value)}</th>`).join('')}</tr>${exportRows().map(row=>`<tr>${row.map(value=>`<td>${escape(value)}</td>`).join('')}</tr>`).join('')}</table></body></html>`,'application/vnd.ms-excel;charset=utf-8','xls')};
  const exportPdf=()=>{const escape=(value:any)=>String(value).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');const summary=exportSummary();const financialCards=[['Receitas',summary.revenueCount,brl(summary.revenueValue),'income'],['Despesas',summary.expenseCount,brl(summary.expenseValue),'expense'],['Transferências',summary.transferCount,brl(summary.transferValue),'transfer'],['Pendentes',summary.pendingCount,brl(summary.pendingValue),'pending'],['Pagos',summary.paidCount,brl(summary.paidValue),'paid']];const win=window.open('','_blank','width=1000,height=720');if(!win)return;win.document.write(`<html><head><title>Transações ${period}</title><style>body{font-family:Arial;padding:30px;color:#241820}h1{color:#7f2854;margin-bottom:5px}.summary{display:grid;grid-template-columns:repeat(3,1fr);gap:11px;margin:22px 0 12px}.summary-card{padding:14px;border:1px solid #e4d8de;border-radius:10px;background:#faf6f8;position:relative}.summary-card b,.summary-card span{display:block}.summary-card b{font-size:11px;color:#7f2854;text-transform:uppercase;margin-bottom:9px}.summary-card .count{position:absolute;right:12px;top:10px;min-width:28px;height:28px;border-radius:14px;background:#7f2854;color:#fff;display:grid;place-items:center;font-size:14px;font-weight:bold}.summary-card .value{font-size:17px;font-weight:bold}.summary-card.income{border-top:4px solid #15875d}.summary-card.expense{border-top:4px solid #c13d4e}.summary-card.transfer{border-top:4px solid #6670f0}.summary-card.pending{border-top:4px solid #d38b22}.summary-card.paid{border-top:4px solid #2f9961}.generated{display:flex;gap:12px;margin:0 0 28px}.generated div{flex:1;padding:10px 13px;border-radius:8px;background:#f3ebef}.generated b{color:#7f2854;font-size:11px;text-transform:uppercase;margin-right:7px}.result{padding:13px;margin-bottom:12px;border-radius:9px;background:#ede9ff;color:#4f46b8;font-weight:bold}table{width:100%;border-collapse:collapse}th,td{padding:9px;border-bottom:1px solid #ddd;text-align:left;font-size:12px}th{background:#7f2854;color:#fff;text-transform:uppercase;letter-spacing:.3px}@media print{body{padding:5px}.summary,.generated,.result{break-inside:avoid}}</style></head><body><h1>Juntos Finance — Transações</h1><p>Período: ${period} · ${filtered.length} registros</p><section class="summary">${financialCards.map(card=>`<div class="summary-card ${card[3]}"><b>${escape(card[0])}</b><strong class="count">${card[1]}</strong><span class="value">${escape(card[2])}</span></div>`).join('')}</section><div class="result">Resultado: ${escape(brl(summary.result))}</div><section class="generated"><div><b>Gerado em</b>${summary.date}</div><div><b>Horário</b>${summary.time}</div></section><table><thead><tr>${exportHeaders.map(value=>`<th>${escape(value)}</th>`).join('')}</tr></thead><tbody>${exportRows().map(row=>`<tr>${row.map(value=>`<td>${escape(value)}</td>`).join('')}</tr>`).join('')}</tbody></table><script>window.onload=()=>window.print()<\/script></body></html>`);win.document.close();setExportOpen(false)};  return <div className="page-stack"><div className="page-heading"><div><p>Controle financeiro</p><h1>Transações</h1><span>Acompanhe tudo que entra e sai.</span></div><div className="transactions-page-actions"><div className="transaction-export-menu" ref={exportRef}><button type="button" className="ghost" onClick={()=>setExportOpen(!exportOpen)} aria-expanded={exportOpen}><Download size={17}/> Exportar <ChevronDown size={15}/></button>{exportOpen&&<div className="transaction-export-options"><button onClick={exportCsv}><b>CSV</b><small>Planilhas e importações</small></button><button onClick={exportExcel}><b>Excel</b><small>Arquivo .xls</small></button><button onClick={exportPdf}><b>PDF</b><small>Imprimir ou salvar em PDF</small></button></div>}</div><NewTransactionButton onSelect={type=>onNew(type)}/></div></div><div className="metrics-grid compact transactions-total-metric"><MetricCard label="Total das transações" value={brl(filteredTotal)} detail={`${filtered.length} ${filtered.length===1?'transação selecionada':'transações selecionadas'}`} icon={ReceiptText} tone="purple" hide={!metricVisibility.total} onToggleHide={()=>toggleMetricVisibility('total')}/></div><section className="card table-card"><div className="toolbar"><label className="search"><Search size={17}/><input value={query} onChange={e=>setQuery(e.target.value)} placeholder="Buscar transação..."/></label><select className="ghost toolbar-select" value={person} onChange={e=>setPerson(e.target.value)}><option value="Todas">Todos</option>{transactionTypeView!=='income'&&<><option value="Rafael">{people.Rafael.name||'Você'}</option>{isCouple&&<><option value="Mariana">{people.Mariana.name||'Parceiro(a)'}</option><option value="Casal">Ambos</option></>}</>}</select><button type="button" className={`ghost hide-income-toggle ${hideIncome?'active':''}`} onClick={()=>setHideIncome(value=>!value)} aria-pressed={hideIncome}>{hideIncome?'Mostrar receitas':'Ocultar receitas'}</button><select className="ghost toolbar-select transaction-type-view-select" value={transactionTypeView} onChange={e=>{const value=e.target.value as typeof transactionTypeView;setTransactionTypeView(value);if(value==='income')setPerson('Todas')}} aria-label="Filtrar tipo de transação"><option value="all">Todas as transações</option><option value="income">Receitas</option><option value="expense">Despesas</option><option value="transfer">Transferências</option></select><select className="ghost toolbar-select behavior-view-select" value={behaviorView} onChange={e=>setBehaviorView(e.target.value as typeof behaviorView)} aria-label="Filtrar comportamento"><option value="all">Todos os tipos</option><option value="fixed">Fixos</option><option value="variable">Variáveis</option><option value="installments">Parcelados</option></select><input className="ghost toolbar-month" type="month" value={period} onChange={e=>setPeriod(e.target.value)}/></div><div className="transactions-detail-table"><div className="transactions-detail-head"><span>Situação</span><span>Descrição</span><span>Categoria</span><span>Conta</span><span>Data da efetivação</span><span>Valor</span><span>Editar</span></div>{filtered.length?filtered.map(t=>{const paid=t.status==='Pago'||t.status==='Efetivada';const situation=paid?'Pago':'Pendente';return <div className="transactions-detail-row" key={t.id}>{t.type==='in'?<span className="transaction-situation-empty" aria-label="Situação não aplicável para receita">—</span>:<button type="button" className={`transaction-situation ${situation.toLowerCase()}`} onClick={()=>openPayment(t)} aria-label={`${situation}. Clique para alterar`} title="Clique para alterar a situação">{paid?<Check size={15}/>:<CalendarDays size={15}/>}<span>{situation}</span></button>}<span className="transaction-description"><i className={`transaction-icon ${t.type}`}>{categoryIconFor(t.category,t.icon)}</i><span><b>{displayTitle(people,t.title)}</b><small>{displayPerson(people,t.person)} · {(t.scope||'personal')==='shared'?'Compartilhada':'Pessoal'}{t.notes?` · ${t.notes}`:''}</small></span></span><span className="transaction-category-cell" data-label="Categoria"><span>{t.category||'Outros'}</span><small className={`transaction-behavior ${transactionBehavior(t)}`}>{transactionBehavior(t)==='installments'?'Parcelada':transactionBehavior(t)==='fixed'?'Fixa':'Variável'}</small></span><span data-label="Conta">{t.account||t.card||'Não informada'}</span>{t.type==='in'?<span data-label="Data da efetivação">Efetivada em {new Date((t.dateInput||t.createdAt||new Date().toISOString()).slice(0,10)+'T12:00:00').toLocaleDateString('pt-BR')}</span>:<button type="button" className="transaction-effective-date" data-label="Data da efetivação" onClick={()=>openPayment(t)} title="Alterar situação e data do pagamento">{paid&&t.paidAt?<>Pago em {new Date(t.paidAt).toLocaleDateString('pt-BR')}</>:t.dateInput?<>Prevista: {new Date(t.dateInput+'T12:00:00').toLocaleDateString('pt-BR')}</>:t.date}</button>}<strong className={t.type} data-label="Valor">{t.type === 'in' ? '+' : '−'} {brl(t.value)}</strong><button className="icon-button transaction-edit-button" onClick={()=>openEdit(t)} aria-label={`Editar ${t.title}`} title="Editar transação"><Pencil size={17}/></button></div>}):<div className="organizer-empty">Nenhuma transação encontrada.</div>}</div></section>
    {paymentEditing&&<div className="modal-backdrop" onMouseDown={e=>e.target===e.currentTarget&&setPaymentEditing(null)}><form className="modal payment-status-modal" onSubmit={savePayment}><div className="edit-modal-head"><div><span>EFETIVAÇÃO</span><h2>Situação do pagamento</h2><p>{paymentEditing.title}</p></div><button type="button" className="icon-button" onClick={()=>setPaymentEditing(null)} aria-label="Fechar"><X size={19}/></button></div><div className="payment-status-body"><label>Situação<select value={paymentEditing.status} onChange={e=>setPaymentEditing({...paymentEditing,status:e.target.value})}><option>Pago</option><option>Pendente</option></select></label>{paymentEditing.status==='Pago'&&<label>Data em que foi pago<input type="date" max={new Intl.DateTimeFormat('en-CA').format(new Date())} value={paymentEditing.paidDate} onChange={e=>setPaymentEditing({...paymentEditing,paidDate:e.target.value})} required/></label>}<p>{paymentEditing.status==='Pendente'?'A data prevista original será mantida até o pagamento.':'Escolha o dia correto em que a despesa foi paga.'}</p></div><div className="edit-modal-actions"><button type="button" className="ghost" onClick={()=>setPaymentEditing(null)}>Cancelar</button><button className="primary"><Check size={17}/> Salvar</button></div></form></div>}
    {editing&&<div className="modal-backdrop" onMouseDown={e=>e.target===e.currentTarget&&setEditing(null)}><form className="modal edit-transaction-modal" onSubmit={saveEdit}><div className="edit-modal-head"><div><span>EDITAR MOVIMENTAÇÃO</span><h2>Editar transação</h2><p>Atualize os dados do lançamento selecionado.</p></div><button type="button" className="icon-button" onClick={()=>setEditing(null)}><X size={19}/></button></div><div className="type-switch edit-types"><button type="button" className={editForm.type==='in'?'active':''} onClick={()=>setEditForm({...editForm,type:'in',icon:'↗'})}>Receita</button><button type="button" className={editForm.type==='out'?'active':''} onClick={()=>setEditForm({...editForm,type:'out',icon:'−'})}>Despesa</button></div><div className="edit-form-grid"><label className="field-full">Descrição<input value={editForm.title||''} onChange={e=>setEditForm({...editForm,title:e.target.value})} required/></label><label>Valor (R$)<input value={editForm.value||''} onChange={e=>setEditForm({...editForm,value:formatMoneyInput(e.target.value)})} inputMode="decimal" required/></label><label>Data<input type="date" value={editForm.dateInput||''} onChange={e=>setEditForm({...editForm,dateInput:e.target.value})}/></label><label>Categoria<select value={editForm.category||''} onChange={e=>setEditForm({...editForm,category:e.target.value})}>{categories.map(x=><option key={x}>{x}</option>)}</select></label><label>Comportamento<select value={editForm.behavior||(editForm.fixedMonthly?'fixed':'variable')} onChange={e=>setEditForm({...editForm,behavior:e.target.value,schedule:e.target.value==='installments'?'installments':editForm.schedule==='installments'?'once':editForm.schedule})}><option value="fixed">Fixa</option><option value="variable">Variável</option><option value="installments">Parcelada</option></select></label><label>Responsável<select value={editForm.person||'Rafael'} onChange={e=>setEditForm({...editForm,person:e.target.value})}><option value="Rafael">{people.Rafael.name||'Você'}</option>{isCouple&&<><option value="Mariana">{people.Mariana.name||'Parceiro(a)'}</option><option value="Casal">Ambos</option></>}</select></label>{editForm.type==='out'&&<label>Situação<select value={editForm.status||'Pendente'} onChange={e=>setEditForm({...editForm,status:e.target.value,paidAt:e.target.value==='Pago'?(editForm.paidAt||new Date().toISOString()):null})}><option>Pago</option><option>Pendente</option></select></label>}<label className="field-full">Conta<input value={editForm.account||editForm.card||''} onChange={e=>setEditForm({...editForm,account:e.target.value})} placeholder="Conta ou cartão"/></label></div><div className="edit-modal-actions"><button type="button" className="ghost danger delete-transaction" onClick={()=>remove(editing)}>Excluir</button><span/><button type="button" className="ghost" onClick={()=>setEditing(null)}>Cancelar</button><button className="primary"><Check size={17}/> Salvar alterações</button></div></form></div>}
  </div>;
}

const PLANNING_MODELS=[
  {id:'traditional',name:'Tradicional',formula:'50/30/20',description:'Uma divisão simples para começar.',segments:[{name:'Necessidades',percent:50,icon:'🏠',color:'#7c3aed'},{name:'Desejos',percent:30,icon:'🎯',color:'#d39155'},{name:'Poupança/Investimentos',percent:20,icon:'💰',color:'#07875d'}]},
  {id:'balanced',name:'Equilibrado',formula:'50/15/20/15',description:'Equilibra segurança, objetivos e lazer.',segments:[{name:'Necessidades',percent:50,icon:'🏠',color:'#7c3aed'},{name:'Reserva/Investimentos',percent:15,icon:'💰',color:'#07875d'},{name:'Metas',percent:20,icon:'🎯',color:'#3b82f6'},{name:'Lazer',percent:15,icon:'🎉',color:'#d39155'}]},
  {id:'security',name:'Segurança',formula:'60/20/10/10',description:'Prioriza despesas essenciais e reserva.',segments:[{name:'Necessidades',percent:60,icon:'🏠',color:'#7c3aed'},{name:'Reserva/Investimentos',percent:20,icon:'💰',color:'#07875d'},{name:'Metas',percent:10,icon:'🎯',color:'#3b82f6'},{name:'Lazer',percent:10,icon:'🎉',color:'#d39155'}]},
  {id:'goals',name:'Metas',formula:'60/10/20/10',description:'Direciona uma parcela maior aos objetivos.',segments:[{name:'Necessidades',percent:60,icon:'🏠',color:'#7c3aed'},{name:'Reserva/Investimentos',percent:10,icon:'💰',color:'#07875d'},{name:'Metas',percent:20,icon:'🎯',color:'#3b82f6'},{name:'Lazer',percent:10,icon:'🎉',color:'#d39155'}]},
  {id:'custom',name:'Personalizado',formula:'Você decide',description:'Escolha nomes e percentuais.',segments:[]}
];function BudgetsPage(){
  const initial:any[]=[];
  const [items,setItems]=useState<any[]>(initial); const [editing,setEditing]=useState<any|null>(null); const [tx,setTx]=useState<any[]>(transactions); const [period,setPeriod]=useState(()=>new Intl.DateTimeFormat('en-CA').format(new Date()).slice(0,7)); const [planningModel,setPlanningModel]=useState('traditional'); const [planningIncome,setPlanningIncome]=useState(''); const [customSegments,setCustomSegments]=useState([{name:'Necessidades',percent:50,icon:'🏠',color:'#7c3aed'},{name:'Investimentos',percent:30,icon:'💰',color:'#07875d'},{name:'Lazer',percent:20,icon:'🎉',color:'#d39155'}]);
  const categories=['Moradia','Alimentação','Mercado','Restaurante','Delivery','Transporte','Combustível','Aluguel','Condomínio','Internet','Luz','Água','Telefone','Saúde','Educação','Filhos','Viagens','Lazer','Compras','Assinaturas','Investimentos','Dívidas','Seguros','Impostos','Outros'];
  useEffect(()=>{const saved=localStorage.getItem('juntos-budgets');if(saved)setItems(JSON.parse(saved));try{const plan=JSON.parse(localStorage.getItem('juntos-planning-model')||'null');if(plan){setPlanningModel(plan.model||'traditional');setPlanningIncome(plan.income||'');if(Array.isArray(plan.customSegments)&&plan.customSegments.length)setCustomSegments(plan.customSegments)}}catch{}const load=()=>{const data=localStorage.getItem('juntos-transactions');setTx(data?JSON.parse(data):transactions)};load();window.addEventListener('juntos-transactions-updated',load);return()=>window.removeEventListener('juntos-transactions-updated',load)},[]);
  const persist=(next:any[])=>{setItems(next);localStorage.setItem('juntos-budgets',JSON.stringify(next));window.dispatchEvent(new Event('juntos-budgets-updated'))}; const spent=(b:any)=>tx.filter(t=>t.type==='out'&&(!t.dateInput||t.dateInput.startsWith(period))&&(t.category===b.category||(b.theme==='fixed'&&['Aluguel','Condomínio','Internet','Luz','Água','Telefone'].includes(t.category)))).reduce((s,t)=>s+Number(t.value),0);
  const openNew=()=>setEditing({id:Date.now(),name:'',category:'Lazer',limit:'',theme:'leisure',icon:'🎯',color:'#7c3aed',isNew:true}); const save=(e:React.FormEvent)=>{e.preventDefault();const item={...editing,limit:Number(String(editing.limit).replace(/[.]/g,'').replace(',','.'))};delete item.isNew;if(!item.name.trim()||item.limit<=0)return;persist(editing.isNew?[...items,item]:items.map(x=>x.id===item.id?item:x));setEditing(null);appAction(editing.isNew?'Orçamento criado com sucesso.':'Orçamento atualizado com sucesso.')}; const remove=async()=>{if(editing&&!editing.isNew&&await confirmDialog(`Excluir “${editing.name}”?`)){persist(items.filter(x=>x.id!==editing.id));setEditing(null);appAction('Orçamento excluído.')}};
  const totalLimit=items.reduce((s,x)=>s+Number(x.limit),0),totalSpent=items.reduce((s,x)=>s+spent(x),0); const registeredIncome=tx.filter(item=>item.type==='in'&&item.dateInput?.startsWith(period)).reduce((sum,item)=>sum+Number(item.value||0),0); const manualIncome=Number(planningIncome.replace(/[.]/g,'').replace(',','.'))||0; const planIncome=manualIncome||registeredIncome; const selectedPlanning=PLANNING_MODELS.find(model=>model.id===planningModel)||PLANNING_MODELS[0]; const planningSegments=planningModel==='custom'?customSegments:selectedPlanning.segments; const planningPercent=planningSegments.reduce((sum,segment)=>sum+Number(segment.percent||0),0); const savePlanning=(model=planningModel,income=planningIncome,segments=customSegments)=>localStorage.setItem('juntos-planning-model',JSON.stringify({model,income,customSegments:segments})); const choosePlanning=(model:string)=>{setPlanningModel(model);savePlanning(model)}; const updateCustomSegment=(index:number,key:string,value:any)=>{const next=customSegments.map((segment,position)=>position===index?{...segment,[key]:value}:segment);setCustomSegments(next);savePlanning(planningModel,planningIncome,next)};
  return <div className="page-stack budgets-page"><div className="page-heading"><div><p>Planejamento mensal</p><h1>Orçamentos</h1><span>Escolha onde gastar e respeite seus limites.</span></div><div className="budget-actions"><input className="ghost toolbar-month" type="month" value={period} onChange={e=>setPeriod(e.target.value)}/><button className="primary" onClick={openNew}><Plus size={18}/> Novo orçamento</button></div></div><section className="card planning-models"><div className="section-title"><div><h3>Modelos de planejamento</h3><p>Escolha como distribuir sua renda mensal.</p></div><label className="planning-income">Renda para planejar<input value={planningIncome} onChange={event=>{const value=formatMoneyInput(event.target.value);setPlanningIncome(value);savePlanning(planningModel,value)}} placeholder={registeredIncome?brl(registeredIncome):'0,00'} inputMode="decimal"/><small>{manualIncome?'Valor informado manualmente':registeredIncome?'Usando as receitas registradas no mês':'Cadastre uma receita ou informe o valor'}</small></label></div><div className="planning-model-grid">{PLANNING_MODELS.map(model=><button type="button" className={planningModel===model.id?'active':''} onClick={()=>choosePlanning(model.id)} key={model.id}><span><b>{model.name}</b><strong>{model.formula}</strong></span><small>{model.description}</small></button>)}</div>{planningModel==='custom'&&<div className="custom-planning-editor"><div className="custom-planning-head"><b>Categorias personalizadas</b><button type="button" className="ghost" onClick={()=>{const next=[...customSegments,{name:'Nova categoria',percent:0,icon:'📌',color:'#8b5cf6'}];setCustomSegments(next);savePlanning(planningModel,planningIncome,next)}}><Plus size={15}/> Categoria</button></div>{customSegments.map((segment,index)=><div className="custom-planning-row" key={index}><input className="custom-icon" value={segment.icon} onChange={event=>updateCustomSegment(index,'icon',event.target.value)} maxLength={4} aria-label="Ícone"/><input value={segment.name} onChange={event=>updateCustomSegment(index,'name',event.target.value)} placeholder="Nome da categoria"/><label><input type="number" min="0" max="100" value={segment.percent} onChange={event=>updateCustomSegment(index,'percent',Number(event.target.value))}/><span>%</span></label><input type="color" value={segment.color} onChange={event=>updateCustomSegment(index,'color',event.target.value)} aria-label="Cor"/><button type="button" className="icon-button" onClick={()=>{const next=customSegments.filter((_,position)=>position!==index);setCustomSegments(next);savePlanning(planningModel,planningIncome,next)}} aria-label={`Excluir ${segment.name}`}><X size={16}/></button></div>)}<div className={`planning-total ${planningPercent===100?'valid':'invalid'}`}><span>Total dos percentuais</span><b>{planningPercent}%</b><small>{planningPercent===100?'Distribuição completa.':planningPercent<100?`Faltam ${100-planningPercent}%.`:`Ultrapassou ${planningPercent-100}%.`}</small></div></div>}<div className="planning-allocation">{planningSegments.map((segment,index)=><article key={`${segment.name}-${index}`}><i style={{background:`${segment.color}18`,color:segment.color}}>{segment.icon}</i><span><b>{segment.name}</b><small>{segment.percent}% da renda</small></span><strong>{brl(planIncome*Number(segment.percent||0)/100)}</strong><div><span style={{width:`${Math.min(100,Number(segment.percent||0))}%`,background:segment.color}}/></div></article>)}</div>{planningModel==='custom'&&planningPercent!==100&&<p className="planning-warning">Ajuste os percentuais para totalizar 100% e obter um planejamento completo.</p>}</section><div className="budget-grid">{items.map(b=>{const used=spent(b),pct=Math.min(100,Math.round(used/b.limit*100)||0),remaining=b.limit-used;return <article className={`card budget-card ${remaining<0?'over':''}`} key={b.id}><button className="budget-edit" onClick={()=>setEditing({...b,limit:String(b.limit).replace('.',',')})} aria-label={`Editar ${b.name}`}><MoreHorizontal size={18}/></button><div className="budget-card-head"><div className="budget-icon" style={{background:`${b.color}18`,color:b.color}}>{b.icon}</div><div className="budget-card-heading"><span>{b.theme==='fixed'?'DESPESA FIXA':b.theme==='leisure'?'LAZER':b.theme==='saving'?'RESERVA':'VARIÁVEL'}</span><h3>{b.name}</h3><small>{b.category}</small></div></div><div className="budget-values"><b>{brl(used)}</b><span>de {brl(b.limit)}</span></div><div className="progress"><span style={{width:`${pct}%`,background:remaining<0?'#c13d4e':b.color}}/></div><div className="budget-foot"><span>{pct}% utilizado</span><strong className={remaining<0?'down':'up'}>{remaining<0?`${brl(Math.abs(remaining))} acima`:`${brl(remaining)} disponível`}</strong></div>{remaining<0&&<div className="budget-limit-alert"><Bell size={15}/><span><b>Limite ultrapassado</b><small>Você excedeu este orçamento em {brl(Math.abs(remaining))}.</small></span></div>}</article>})}</div>
        {editing&&<div className="modal-backdrop" onMouseDown={e=>e.target===e.currentTarget&&setEditing(null)}><form className="modal budget-editor" onSubmit={save}><div className="edit-modal-head"><div><span>{editing.isNew?'NOVO ORÇAMENTO':'EDITAR ORÇAMENTO'}</span><h2>{editing.isNew?'Criar limite de gastos':'Atualizar limite'}</h2><p>Escolha o tema e quanto deseja gastar.</p></div><button type="button" className="icon-button" onClick={()=>setEditing(null)}><X/></button></div><div className="budget-edit-grid"><label className="field-full">Nome do orçamento<input value={editing.name} onChange={e=>setEditing({...editing,name:e.target.value})} placeholder="Ex.: Lazer de fim de semana" required/></label><label>Tema<select value={editing.theme} onChange={e=>setEditing({...editing,theme:e.target.value})}><option value="fixed">Despesa fixa</option><option value="leisure">Lazer</option><option value="variable">Gasto variável</option><option value="saving">Reserva</option></select></label><label>Categoria<select value={editing.category} onChange={e=>setEditing({...editing,category:e.target.value})}>{categories.map(x=><option key={x}>{x}</option>)}</select></label><label>Limite mensal<input value={editing.limit} onChange={e=>setEditing({...editing,limit:formatMoneyInput(e.target.value)})} placeholder="0,00" inputMode="decimal" required/></label><label>Ícone<input value={editing.icon} onChange={e=>setEditing({...editing,icon:e.target.value})} maxLength={4}/></label><label>Cor<input type="color" value={editing.color} onChange={e=>setEditing({...editing,color:e.target.value})}/></label></div><div className="edit-modal-actions">{!editing.isNew&&<button type="button" className="ghost danger" onClick={remove}>Excluir orçamento</button>}<span/><button type="button" className="ghost" onClick={()=>setEditing(null)}>Cancelar</button><button className="primary"><Check size={17}/> Salvar orçamento</button></div></form></div>}
  </div>
}
function AccountsPage({people,setPeople,balances,setBalances,isCouple}:{people:any;setPeople:any;balances:any;setBalances:any;isCouple:boolean}) {
  const [accounts,setAccounts]=useState<any[]>([]); const [editing,setEditing]=useState<any|null>(null); const [transfer,setTransfer]=useState<any|null>(null);
  useEffect(()=>{const saved=localStorage.getItem('juntos-accounts');setAccounts(saved?JSON.parse(saved):[])},[]);
  const persist=(next:any[])=>{setAccounts(next);localStorage.setItem('juntos-accounts',JSON.stringify(next));const nextBalances={...balances,couple:0,rafael:0,mariana:0,investments:0};next.forEach(a=>{if(a.id in nextBalances)nextBalances[a.id]=Number(a.value)});setBalances(nextBalances);localStorage.setItem('juntos-balances',JSON.stringify(nextBalances))};
  const openNew=()=>setEditing({id:'account-'+Date.now(),name:'',bank:'',type:'Conta corrente',value:'',color:'violet',scope:'personal',owner:'Rafael',isNew:true});
  const saveAccount=(e:React.FormEvent)=>{e.preventDefault();const value=Number(String(editing.value).replace(/[.]/g,'').replace(',','.'));if(!editing.name.trim()||!editing.bank.trim()||Number.isNaN(value))return;const account={...editing,name:editing.name.trim(),bank:editing.bank.trim(),value};delete account.isNew;const next=editing.isNew?[...accounts,account]:accounts.map(a=>a.id===account.id?account:a);persist(next);if(account.id==='rafael')setPeople({...people,Rafael:{...people.Rafael,name:account.name}});if(account.id==='mariana')setPeople({...people,Mariana:{...people.Mariana,name:account.name}});setEditing(null);appAction(editing.isNew?'Conta criada com sucesso.':'Conta atualizada em todo o aplicativo.')};
  const deleteAccount=async()=>{if(!editing||!await confirmDialog(`Excluir a conta ${editing.name}?`))return;persist(accounts.filter(a=>a.id!==editing.id));setEditing(null);appAction('Conta excluída.')};
  const saveTransfer=async(e:React.FormEvent)=>{e.preventDefault();const value=Number(String(transfer.value).replace(/[.]/g,'').replace(',','.'));if(!transfer.from||!transfer.to||transfer.from===transfer.to||value<=0)return;const origin=accounts.find(a=>a.id===transfer.from);if(!origin||origin.value<value){await alertDialog('Saldo insuficiente na conta de origem.');return}persist(accounts.map(a=>a.id===transfer.from?{...a,value:a.value-value}:a.id===transfer.to?{...a,value:a.value+value}:a));setTransfer(null);appAction('Transferência concluída com sucesso.')};
  const total=accounts.reduce((sum,a)=>sum+Number(a.value||0),0);
  return <div className="page-stack"><div className="page-heading"><div><p>Patrimônio</p><h1>Contas</h1><span>Todos os saldos em um só lugar.</span></div><button className="primary" onClick={openNew}><Plus size={18}/> Nova conta</button></div><div className="account-grid">{accounts.length?accounts.map(a=><article className="card account" key={a.id}><div className={`bank-icon ${a.color}`}><Landmark/></div><button className="icon-button" onClick={()=>setEditing({...a,value:String(a.value).replace('.',',')})} aria-label={`Editar ${a.name}`}><MoreHorizontal size={18}/></button><span>{a.bank}</span><h3>{a.name}</h3><small>{a.type} · {(a.scope||'personal')==='shared'?'Compartilhada':a.owner==='Mariana'?'Do parceiro(a)':'Pessoal'}</small><strong>{brl(a.value)}</strong><div className="account-foot"><span>Sem movimentações</span></div></article>):<div className="organizer-empty">Nenhuma conta cadastrada.</div>}</div><section className="card table-card"><div className="section-title"><div><h3>Visão consolidada</h3><p>Saldo por instituição</p></div><button className="ghost" disabled={accounts.length<2} onClick={()=>setTransfer({from:accounts[0]?.id||'',to:accounts[1]?.id||'',value:''})}>Transferir entre contas</button></div><div className="metrics-grid compact"><MetricCard label="Saldo total" value={brl(total)} detail={`${accounts.length} contas cadastradas`} icon={WalletCards} tone="purple"/><MetricCard label="Entradas" value={brl(0)} detail="Sem movimentações" icon={TrendingUp} tone="positive"/><MetricCard label="Saídas" value={brl(0)} detail="Sem movimentações" icon={TrendingDown} tone="negative"/></div><div className="bar-wrap"><ResponsiveContainer width="100%" height="100%"><ReBarChart data={accounts} layout="vertical" margin={{left:20,right:30}}><CartesianGrid strokeDasharray="4 4" horizontal={false}/><XAxis type="number" hide/><YAxis type="category" dataKey="bank" axisLine={false} tickLine={false}/><Tooltip formatter={(v)=>brl(Number(v))}/><Bar dataKey="value" fill="#7f2854" radius={[0,8,8,0]}/></ReBarChart></ResponsiveContainer></div></section>
        {editing&&<div className="modal-backdrop" onMouseDown={e=>e.target===e.currentTarget&&setEditing(null)}><form className="modal account-editor" onSubmit={saveAccount}><div className="edit-modal-head"><div><span>{editing.isNew?'NOVA CONTA':'EDITAR CONTA'}</span><h2>{editing.isNew?'Adicionar conta':'Configurar conta'}</h2><p>Atualize todas as informações e o saldo.</p></div><button type="button" className="icon-button" onClick={()=>setEditing(null)}><X size={19}/></button></div><div className="account-edit-grid"><label>Nome da conta<input value={editing.name} onChange={e=>setEditing({...editing,name:e.target.value})} required/></label><label>Instituição<input value={editing.bank} onChange={e=>setEditing({...editing,bank:e.target.value})} placeholder="Ex.: Nubank" required/></label><label>Tipo<select value={editing.type} onChange={e=>setEditing({...editing,type:e.target.value})}><option>Conta corrente</option><option>Conta individual</option><option>Carteira</option><option>Investimentos</option><option>Poupança</option></select></label>{isCouple&&<><label>Uso da conta<select value={editing.scope||'personal'} onChange={e=>setEditing({...editing,scope:e.target.value})}><option value="personal">Pessoal</option><option value="shared">Compartilhada</option></select></label>{(editing.scope||'personal')==='personal'&&<label>Responsável<select value={editing.owner||'Rafael'} onChange={e=>setEditing({...editing,owner:e.target.value})}><option value="Rafael">Você</option><option value="Mariana">Parceiro(a)</option></select></label>}</>}<label>Saldo<input value={editing.value} onChange={e=>setEditing({...editing,value:formatMoneyInput(e.target.value)})} inputMode="decimal" required/></label><label>Cor<select value={editing.color} onChange={e=>setEditing({...editing,color:e.target.value})}><option value="violet">Roxo</option><option value="orange">Laranja</option><option value="amber">Amarelo</option><option value="dark">Preto</option></select></label></div><div className="edit-modal-actions">{!editing.isNew&&<button type="button" className="ghost danger delete-account" onClick={deleteAccount}>Excluir conta</button>}<span/><button type="button" className="ghost" onClick={()=>setEditing(null)}>Cancelar</button><button className="primary"><Check size={17}/> Salvar conta</button></div></form></div>}
    {transfer&&<div className="modal-backdrop" onMouseDown={e=>e.target===e.currentTarget&&setTransfer(null)}><form className="modal transfer-modal" onSubmit={saveTransfer}><div className="edit-modal-head"><div><span>MOVIMENTAÇÃO INTERNA</span><h2>Transferir entre contas</h2><p>O valor será debitado da origem e creditado no destino.</p></div><button type="button" className="icon-button" onClick={()=>setTransfer(null)}><X size={19}/></button></div><div className="account-edit-grid"><label>Conta de origem<select value={transfer.from} onChange={e=>setTransfer({...transfer,from:e.target.value})}>{accounts.map(a=><option value={a.id} key={a.id}>{a.name} — {brl(a.value)}</option>)}</select></label><label>Conta de destino<select value={transfer.to} onChange={e=>setTransfer({...transfer,to:e.target.value})}>{accounts.map(a=><option value={a.id} key={a.id}>{a.name}</option>)}</select></label><label className="field-full">Valor da transferência<input value={transfer.value} onChange={e=>setTransfer({...transfer,value:formatMoneyInput(e.target.value)})} placeholder="0,00" inputMode="decimal" required/></label></div><div className="edit-modal-actions"><span/><button type="button" className="ghost" onClick={()=>setTransfer(null)}>Cancelar</button><button className="primary">Confirmar transferência</button></div></form></div>}
  </div>
}

